COMPANION_REFERENCE = re.compile(
    r'\b(?:Смерт[ьи][ -]из[ -]Тени|Kills[ -]in[ -]Shadow|Лантри|Lantry|'
    r'Эбб?|Eb|Атли|Сирин(?:а|у|ом|е|ы)?|Sirin|Фуг(?:а|у|и|е|ой)|Verse|'
    r'Барик(?:а|у|ом|е)?|Barik|Вершител(?:ь|я|ю|ем|е)(?:\s+судеб)?)\b', re.I)


def _key(text):
    text = re.sub(r'\[/?[^\]]+\]', '', str(text or ''))
    text = COMPANION_REFERENCE.sub('персонаж', text)
    return re.sub(r'\s+', ' ', text).strip().casefold()


@lru_cache(maxsize=1)
def _source_replacements():
    source = json.loads((Path(__file__).parent / 'catalog/ability_rules.json').read_text(encoding='utf-8'))
    by_key = {row['key']: row for row in source['abilities']}
    return {_key(by_key[key]['description']): text for key, text in REVIEWED.items()}


def adapt_gameplay_description(text, source_key=None):
    """Exact reviewed replacements also recognize old DB/cache translations.

    Do not remove arbitrary sentences by keywords: faction names, control effects
    and equipment requirements can be real mechanical conditions.
    """
    if source_key in REVIEWED:
        return REVIEWED[source_key]
    return _source_replacements().get(_key(text), text or '')
